	@Test
	void metadataOnlyWitnessTracksMutationsWithoutReadingLexicalValues() {
		SimpleIRI subject = SimpleModelExposureForTest.simpleIRI("urn:subject");
		SimpleLiteral object = SimpleModelExposureForTest.simpleLiteral("entry");
		Value triple = SimpleModelExposureForTest.simpleTripleTerm(subject, new InternedIRI("urn:", "predicate"),
				object);
		AtomicInteger reservations = new AtomicInteger();
		LmdbValue.ChildVersion witness = LmdbValue.ChildVersion.captureMetadataOnly(triple, bytes -> {
			reservations.incrementAndGet();
			return true;
		});
		assertNotNull(witness);
		assertTrue(witness.isCurrent());
		assertTrue(reservations.get() >= 4, "traversal scratch and each mutable child require admission");
		SimpleModelExposureForTest.setLabel(object, "changed");
		assertFalse(witness.isCurrent());

		ValueStoreRevision revision = new ValueStoreRevision.Default(null);
		LmdbLiteral nativeLiteral = new LmdbLiteral(revision, "original", LmdbValue.UNKNOWN_ID);
		LmdbValue.ChildVersion nativeWitness = LmdbValue.ChildVersion.captureMetadataOnly(nativeLiteral,
				ignored -> true);
		assertNotNull(nativeWitness);
		assertTrue(nativeWitness.isCurrent());
		nativeLiteral.setFromInitializedValue(new LmdbLiteral(revision, "changed", LmdbValue.UNKNOWN_ID));
		assertFalse(nativeWitness.isCurrent());
		assertNull(LmdbValue.ChildVersion.captureMetadataOnly(new LmdbIRI(revision, 19L), ignored -> true),
				"a cold native value has no mutation-safe semantic witness");
		assertNull(LmdbValue.ChildVersion.captureMetadataOnly(SimpleModelExposureForTest.subclassIri("urn:custom"),
				ignored -> true));
		Value unknown = mock(Value.class, invocation -> {
			throw new AssertionError("metadata capture must not call a foreign value accessor");
		});
		assertNull(LmdbValue.ChildVersion.captureMetadataOnly(unknown, ignored -> true));
		assertNull(LmdbValue.ChildVersion.captureMetadataOnly(subject, ignored -> false));
	}

	@Test
	void metadataOnlyWitnessRejectsCyclesAndTracksDeserializedValues() throws Exception {
		ValueStoreRevision revision = new ValueStoreRevision.Default(null);
		SimpleIRI subject = SimpleModelExposureForTest.simpleIRI("urn:subject");
		SimpleIRI predicate = SimpleModelExposureForTest.simpleIRI("urn:predicate");
		LmdbTripleTerm cyclic = new LmdbTripleTerm(revision, subject, predicate, VF.createLiteral("start"));
		LmdbTripleTerm wrapper = new LmdbTripleTerm(revision, subject, predicate, cyclic);
		cyclic.setFromInitializedValue(wrapper);
		assertNull(LmdbValue.ChildVersion.captureMetadataOnly(cyclic, ignored -> true));
		assertNull(LmdbValue.ChildVersion.captureMetadataOnly(
				SimpleModelExposureForTest.simpleTripleTerm(subject, subject, VF.createLiteral("same")),
				ignored -> true),
				"a repeated mutable child cannot be certified by a tree witness");

		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(subject);
		}
		SimpleIRI restored;
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			restored = (SimpleIRI) input.readObject();
		}
		assertEquals(0, restored.getInternalMutationVersion(), "the serialized counter is transient");
		LmdbValue.ChildVersion witness = LmdbValue.ChildVersion.captureMetadataOnly(restored, ignored -> true);
		assertNotNull(witness, "an initialized deserialized object can be witnessed afresh");
		SimpleModelExposureForTest.setIriString(restored, "urn:changed");
		assertFalse(witness.isCurrent());
	}

