	@Test
	void coldNativeValuesPublishOneReadinessTransitionOnLexicalInitialization(@TempDir Path directory)
			throws Exception {
		ValueStore store = new ValueStore(directory.toFile(), new LmdbStoreConfig());
		try {
			long iriId = store.storeValue(store.createIRI("urn:readiness:iri"));
			long literalId = store.storeValue(store.createLiteral("readiness literal"));
			InitializationCountingRevision revision = new InitializationCountingRevision(store);
			LmdbIRI iri = new LmdbIRI(revision, iriId);
			LmdbLiteral literal = new LmdbLiteral(revision, literalId);

			assertFalse(iri.isInitialized());
			assertFalse(literal.isInitialized());
			assertEquals(0, revision.initializedValues.get());
			assertEquals(iriId, iri.getInternalID());
			assertEquals(literalId, literal.getInternalID());
			assertFalse(iri.isInitialized());
			assertFalse(literal.isInitialized());
			assertEquals(0, revision.initializedValues.get(), "identity checks must leave native payloads cold");

			assertEquals("urn:readiness:iri", iri.stringValue());
			assertTrue(iri.isInitialized());
			assertEquals(1, revision.initializedValues.get());
			assertEquals("readiness literal", literal.stringValue());
			assertTrue(literal.isInitialized());
			assertEquals(2, revision.initializedValues.get());
			assertEquals("urn:readiness:iri", iri.stringValue());
			assertEquals("readiness literal", literal.stringValue());
			assertEquals(2, revision.initializedValues.get(), "repeated reads must not republish readiness");
		} finally {
			store.close();
		}
	}

