	@Test
	void mutableSimpleDatatypeUsesRdfEqualityWithoutSharingIdsAndTracksMutation() {
		ValueStoreRevision revision = new ValueStoreRevision.Default(null);
		SimpleIRI datatype = SimpleModelExposureForTest.simpleIRI("urn:datatype:custom");
		LmdbLiteral nativeLiteral = new LmdbLiteral(revision, "custom", datatype, ID);
		Literal stableBeforeMutation = VF.createLiteral("custom", new InternedIRI("urn:datatype:", "custom"));
		long idBeforeMutation = nativeLiteral.getInternalID();
		long semanticVersionBeforeMutation = nativeLiteral.getSemanticVersion();

		assertTrue(nativeLiteral.equals(stableBeforeMutation));
		assertTrue(stableBeforeMutation.equals(nativeLiteral));
		assertEquals(stableBeforeMutation.hashCode(), nativeLiteral.hashCode());

		SimpleModelExposureForTest.setIriString(datatype, "urn:datatype:changed");
		Literal stableAfterMutation = VF.createLiteral("custom", new InternedIRI("urn:datatype:", "changed"));

		assertFalse(nativeLiteral.equals(stableBeforeMutation));
		assertFalse(stableBeforeMutation.equals(nativeLiteral));
		assertTrue(nativeLiteral.equals(stableAfterMutation));
		assertTrue(stableAfterMutation.equals(nativeLiteral));
		long idAfterMutation = nativeLiteral.getInternalID();
		long semanticVersionAfterMutation = nativeLiteral.getSemanticVersion();
		assertEquals(ID, idBeforeMutation, "A witnessed, unchanged datatype preserves the literal's ID");
		assertNotEquals(LmdbValue.UNKNOWN_ID, semanticVersionBeforeMutation,
				"An exact SimpleIRI datatype supplies a semantic mutation witness");
		assertEquals(LmdbValue.UNKNOWN_ID, idAfterMutation, "Mutating the datatype invalidates the old literal ID");
		assertNotEquals(LmdbValue.UNKNOWN_ID, semanticVersionAfterMutation,
				"The mutation advances the known semantic version");
		assertNotEquals(semanticVersionBeforeMutation, semanticVersionAfterMutation,
				"The mutation witness changes when the datatype changes");
		assertEquals(stableAfterMutation.hashCode(), nativeLiteral.hashCode());
	}

	@Test
	void customCoreDatatypeCannotCertifyMutableIriIdentityOrUseHashCache() {
		AtomicInteger storedHashReads = new AtomicInteger();
		ValueStoreRevision revision = new ValueStoreRevision.Default(null) {
			@Override
			public boolean hasCanonicalIds() {
				return true;
			}

			@Override
			public int getStoredHash(long id) {
				storedHashReads.incrementAndGet();
				return 0;
			}
		};
		SimpleIRI datatype = SimpleModelExposureForTest.subclassIri("urn:datatype:custom");
		CountingCoreDatatype coreDatatype = new CountingCoreDatatype(datatype);
		LmdbLiteral left = new LmdbLiteral(revision, "typed", coreDatatype, ID);
		LmdbLiteral right = new LmdbLiteral(revision, "typed", coreDatatype, OTHER_ID);
		LmdbLiteral builtin = new LmdbLiteral(revision, "builtin", CoreDatatype.XSD.STRING, ID);

		boolean equalBeforeMutation = left.equals(right);
		long leftIdBeforeMutation = left.getInternalID();
		long rightIdBeforeMutation = right.getInternalID();
		long semanticVersionBeforeMutation = left.getSemanticVersion();
		int hashBeforeMutation = left.hashCode();
		int expectedHashBeforeMutation = VF.createLiteral("typed", new InternedIRI("urn:datatype:", "custom"))
				.hashCode();

		SimpleModelExposureForTest.setIriString(datatype, "urn:datatype:changed");
		boolean equalToOldDatatype = left
				.equals(VF.createLiteral("typed", new InternedIRI("urn:datatype:", "custom")));
		boolean equalToChangedDatatype = left
				.equals(VF.createLiteral("typed", new InternedIRI("urn:datatype:", "changed")));
		long idAfterMutation = left.getInternalID();
		int hashAfterMutation = left.hashCode();
		int expectedHashAfterMutation = VF.createLiteral("typed", new InternedIRI("urn:datatype:", "changed"))
				.hashCode();

		assertAll("custom datatype values must use RDF equality without trusting mutable child IDs",
				() -> assertTrue(equalBeforeMutation),
				() -> assertEquals(ID, leftIdBeforeMutation,
						"Unsupported custom datatype children keep their historical ID association"),
				() -> assertEquals(OTHER_ID, rightIdBeforeMutation,
						"Unsupported custom datatype children keep their historical ID association"),
				() -> assertEquals(LmdbValue.UNKNOWN_ID, semanticVersionBeforeMutation),
				() -> assertEquals(0, storedHashReads.get()),
				() -> assertEquals(expectedHashBeforeMutation, hashBeforeMutation),
				() -> assertFalse(equalToOldDatatype),
				() -> assertTrue(equalToChangedDatatype),
				() -> assertEquals(ID, idAfterMutation,
						"A semantic fallback must not erase the literal's historical ID association"),
				() -> assertEquals(expectedHashAfterMutation, hashAfterMutation),
				() -> assertEquals(ID, builtin.getInternalID()),
				() -> assertTrue(builtin.getSemanticVersion() != LmdbValue.UNKNOWN_ID));
	}

	@Test
	void customCoreDatatypeGetterIsNotReusedForIdentityChecks() {
		ValueStoreRevision revision = new ValueStoreRevision.Default(null);
		SimpleIRI initialDatatype = SimpleModelExposureForTest.simpleIRI("urn:datatype:initial");
		CountingCoreDatatype coreDatatype = new CountingCoreDatatype(initialDatatype);
		LmdbLiteral literal = new LmdbLiteral(revision, "typed", coreDatatype, ID);
		int readsAfterConstruction = coreDatatype.iriReads();

		coreDatatype.setIri(SimpleModelExposureForTest.simpleIRI("urn:datatype:replacement"));
		long internalId = literal.getInternalID();
		long semanticVersion = literal.getSemanticVersion();
		int readsAfterIdentityChecks = coreDatatype.iriReads();

		assertAll("an arbitrary CoreDatatype getter must not be consulted after publication",
				() -> assertEquals(1, readsAfterConstruction),
				() -> assertEquals(readsAfterConstruction, readsAfterIdentityChecks),
				() -> assertEquals(ID, internalId,
						"Unsupported custom datatype children retain their historical ID association"),
				() -> assertEquals(LmdbValue.UNKNOWN_ID, semanticVersion));
	}

	@Test
	void repeatedEqualityUsesIdFastPath() {
		ValueStoreRevision revision = new ValueStoreRevision.Default(null);
		CountingLiteral unknown = new CountingLiteral(revision, LmdbValue.UNKNOWN_ID);
		CountingLiteral known = new CountingLiteral(revision, ID);

		assertTrue(unknown.equals(known));
		assertTrue(unknown.termReads > 0);
		assertTrue(known.termReads > 0);
		int unknownReads = unknown.termReads;
		int knownReads = known.termReads;

		assertTrue(unknown.equals(known));
		assertTrue(known.equals(unknown));
		assertEquals(unknownReads, unknown.termReads);
		assertEquals(knownReads, known.termReads);
	}

